export declare const SCAN_TITLE = "Scan a live URL for Art. 50(1)";
export declare const SCAN_DESCRIPTION = "Scan one public page (bare domain or http(s) URL, for example stepnetwork.dk) through console.spurvik.com for AI chat widgets and AI SDKs, and check whether a visible EU AI Act Article 50(1) notice is present. Returns JSON: host, status, score, detected widgets and SDKs, a one-line badge.js fix, reportUrl, sandboxUrl, portfolioUrl, upgradeUrls, and statusShieldMarkdown (a live Art. 50 status shield you can offer to add to the project README.md). localhost, private or reserved IPs and internal hosts are refused before any request. 8-second timeout; when the scan service cannot be reached it returns offlineFallback: true with the links and the badge snippet. Heuristic: reads the HTML of one page. Not legal advice.";
export declare const SCAN_URL_FIELD = "Public http(s) URL or bare domain, for example stepnetwork.dk.";
export declare const BATCH_TITLE = "Batch-scan up to 10 domains for Art. 50(1)";
export declare const BATCH_DESCRIPTION = "Scan 1 to 10 public domains or http(s) URLs (for example an agency's client sites) through console.spurvik.com for AI chat widgets and AI SDKs, and check each frontpage for a visible EU AI Act Article 50(1) notice. Every entry is checked first: if any entry is localhost, a private or reserved IP or an internal host, the whole batch is refused and nothing is sent. Returns JSON: totalDomains, gapsFound and one row per host with detectedWidgets, art50NoticeDetected, gap, reportUrl, a one-line badgeSnippet and statusShieldMarkdown, plus portfolioUrl and upgradeUrls (Team \u20AC79/mo, Done-For-You \u20AC199 once per site). At most 4 scans run at once, each with an 8-second timeout; a host the service cannot reach returns offlineFallback: true in its row. Heuristic: reads the HTML of one page per domain. Not legal advice.";
export declare const BATCH_DOMAINS_FIELD = "1 to 10 public http(s) URLs or bare domains, for example [\"stepnetwork.dk\", \"folk.app\"]. Duplicate hosts are scanned once.";
export declare const C2PA_TITLE = "Check an image URL for a C2PA manifest (CDN-strip check)";
export declare const C2PA_DESCRIPTION = "C2PA JUMBF manifest & CDN-strip checker for one public https image URL (PNG, JPEG or WebP, up to 4 MB) \u2014 or a bare public domain / https store page URL, which auto-discovers the frontpage og:image / hero image in 1 hop \u2014 ahead of EU AI Act Art. 50(2) machine-readable marking (applies from 2 December 2026). console.spurvik.com fetches the image once through its SSRF gate and reads the manifest in memory; nothing is stored. Returns JSON: status, mediaType, byteLength, fileName, c2pa { manifestFound, embedded, claimGenerator, signatureMatches, trustAnchor, validationCodes }, whether the URL goes through an image optimizer that strips C2PA (/_next/image, Cloudinary, imgix, Cloudflare /cdn-cgi/image/, Shopify CDN, Jetpack Photon, Webflow CDN) with a fix, a visible \"AI-generated\" notice (<AIDisclosureLabel notice=\"generated\" /> and badge.js data-notice=\"generated\"), and links: the interactive checker, Pro (\u20AC19/mo) and Done-For-You (\u20AC199 once) with appUrl prefilled. Read-only: it never signs or adds a manifest. Only https on port 443, no credentials; localhost, .local, .internal and private or reserved IPs are refused before any request. 15-second timeout; 10 checks per minute per address, shared with console.spurvik.com/c2pa. Not legal advice.";
export declare const C2PA_URL_FIELD = "Public https URL of a PNG, JPEG or WebP image up to 4 MB (e.g. https://example.com/hero.png), or a bare public store domain / https page URL (e.g. charlie-paris.com) to auto-discover its hero image.";
